import sys,re,random; sys.path.insert(0,'/tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/e22fd76a-04d4-41fa-bf12-fc718952c66e/scratchpad')
from h import *
from kparse import rows as SRC_ROWS
stem="Kubiak Cunn 2009"
SRC="Kubiak, P. J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia, 11(1), 131-165."
LCRN="Lane Cove River valley"; NLN="Narrabeen Lagoon catchment area"
PW="fire responses are for plants with 100% leaf scorch in the January 1994 wildfires, Lane Cove River fire began 6 January 1994 and Narrabeen Lagoon fire 8 January 1994, generally of very high intensity (p. 133 and p. 134); Latitude and Longitude converted from 'lat 33° 45' S, long 151° 05' E' (p. 131); Fire_season_categorical derived from fire dates in January 1994; Fire_type wildfire from 'wildfires'; unmarked species counted as native, * = exotic species (576 native and 252 exotic species, p. 145); first flowering Resp = resprouted plants, Seed = plants from seed (p. 145)"
DEF={"R":"majority of adult plants resprouted","K":"majority of adult plants killed","r":"small proportion of adult plants resprouted","k":"small proportion of adult plants killed"}
def fmt(x):
    s=f"{x:.3f}".rstrip('0').rstrip('.'); return s
def w2y(x): return fmt(float(x)/52)
def code_def(code):
    parts=re.findall(r'(p|\?)?([RKrk])',code); out=[]
    for pre,l in parts:
        d=DEF[l]
        if pre=='p': d='probably '+d
        elif pre=='?': d='possibly '+d
        out.append(f"{l} = {d}")
    return f"code '{code}': "+"; ".join(out)
def clean_code(c):
    c=c.strip()
    if re.fullmatch(r'[?pKkRr/; ]+',c): return re.sub(r'\s+','',c),None
    m=re.match(r'^(R)\(1\)m\.i\.f (.*)$',c)
    if m: return 'R(1)m.i.f',f"LCR code printed 'R(1)m.i.f' ((1) = one plant, m.i.f = moderate intensity fire): {m.group(2)}"
    m=re.match(r'^K;r–m\.i\.f71w$',c)
    if m: return 'K;r',"NL code printed 'K;r-m.i.f71w' (m.i.f = moderate intensity fire)"
    return '',c
def parse_name(raw):
    n=raw.strip(); poss='(*?)' in n; exotic=n.startswith('*') and not poss
    n=n.replace('(*?)','',1) if poss else n.lstrip('*')
    n2=re.sub(r'\s*\((s\.lat\.|s\.str\.|syn\. [^)]*)\)','',n)
    n2=n2.replace('“','').replace('”','').replace('–','-').replace('?','')
    t=n2.split(); g=t[0]; rest=t[1:]; sub=''
    for i,x in enumerate(rest):
        if x in('subsp.','var.','f.'): sub=' '.join(rest[i:]); rest=rest[:i]; break
    sp=' '.join(rest)
    plain=f"{g} {sp}"+(f" {sub}" if sub else '')
    note=None
    if raw.strip()!=plain: note=f"name printed as '{raw.strip()}'"
    return g,sp,sub,exotic,poss,note
UNIT={'w':'weeks','y':'years'}
def parse_time(cell):
    """returns (underline, items) ; item = dict(lo,hi,plus,unit,q,bold,suffix,raw)"""
    u='<u>' in cell
    c=cell.replace('<u>','').replace('</u>','').strip()
    parts=[]; 
    # split on comma / & keeping bold markers
    for seg in re.split(r',| & ',c):
        seg=seg.strip()
        if not seg: continue
        bold='**' in seg
        s=seg.replace('**','').strip()
        m=re.match(r'^(\?)?(c\.)?\s*(\?)?(\d+(?:\.\d+)?)(?:[–-](\d+(?:\.\d+)?))?(\+)?\s*([wy])?(.*)$',s)
        if not m: parts.append(dict(raw=s,bad=True,bold=bold)); continue
        q=bool(m.group(1) or m.group(3) or '?' in m.group(8)); cc=bool(m.group(2))
        parts.append(dict(raw=s,lo=m.group(4),hi=m.group(5),plus=bool(m.group(6)),unit=m.group(7),q=q,c=cc,bold=bold,suffix=m.group(8).strip(),bad=False))
    # inherit unit
    units=[p['unit'] for p in parts if not p.get('bad') and p['unit']]
    dflt=units[-1] if units else 'w'
    for p in parts:
        if not p.get('bad') and not p['unit']: p['unit']=dflt
    return u,parts
def to_years(p):
    if p['unit']=='y': lo,hi=p['lo'],p['hi']
    else: lo,hi=w2y(p['lo']),(w2y(p['hi']) if p['hi'] else None)
    return lo if not hi else f"{lo}-{hi}"
def val_fixed(parts,col,notes,label):
    """first non-bold item (or sole bold) -> years string; returns value or ''"""
    ok=[p for p in parts if not p.get('bad')]
    if not ok: return ''
    first=next((p for p in ok if not p['bold']),ok[0])
    sfx=first['suffix']
    if re.search(r'buds',sfx): 
        notes.append(f"{label} printed '{first['raw']}' (flowers in bud), not filled"); return ''
    v=to_years(first)
    if first['unit']=='w':
        rng=first['lo']+('-'+first['hi'] if first['hi'] else '')
        notes.append(f"{col} converted from {rng} weeks")
    extra=[]
    if first['q'] or first['c']: extra.append("marks '?' or 'c.' removed")
    if sfx: extra.append(f"suffix '{sfx}' printed")
    if extra: notes.append(f"{col} printed '{cell_print(parts)}': "+'; '.join(extra))
    others=[p for p in ok if p is not first]
    if others: notes.append(f"{label} also printed "+', '.join(("sizable proportion flowering at " if o['bold'] else "")+o['raw'] for o in others)+" (bold = sizable proportion of population flowering)")
    return v
def cell_print(parts): return ','.join(p['raw'] for p in parts)
def pjp(cell,col,notes,variable):
    c=cell.strip()
    m=re.fullmatch(r'At least (\d+) years?',c)
    if m: notes.append(f"{col} printed '{c}'"); return '>'+m.group(1),'years'
    m=re.fullmatch(r'Less than (\d+) years?',c)
    if m: notes.append(f"{col} printed '{c}'"); return '<'+m.group(1),'years'
    u,parts=parse_time(c)
    ok=[p for p in parts if not p.get('bad')]
    if not ok: notes.append(f"{col} printed '{c}', not filled"); return '',''
    p=ok[0]
    mark=[]
    if p['q'] or p['c']: mark.append("marks '?' or 'c.' removed")
    if p['suffix']: mark.append(f"suffix '{p['suffix']}'")
    if variable:
        rng=p['lo']+('-'+p['hi'] if p['hi'] else '')
        v=('>' if p['plus'] else '')+rng
        unit=UNIT[p['unit']]
    else:
        v=('>' if p['plus'] else '')+to_years(p)
        unit='years'
        if p['unit']=='w':
            rng=p['lo']+('-'+p['hi'] if p['hi'] else '')
            notes.append(f"{col} converted from {rng} weeks")
    if p['plus'] and not variable: v=('>' if False else '')+v
    if mark or p['plus']: notes.append(f"{col} printed '{c}'"+(': '+'; '.join(mark+(["'+' read as open lower bound"] if p['plus'] else [])) if (mark or p['plus']) else ''))
    return v,unit
def build(raw_row):
    page,sec,c,ln=raw_row
    fam,name,peak,lcr,nl,seed,ffr,ffs,frr,frs,pj,sj=c
    g,sp,sub,exotic,poss,nnote=parse_name(name)
    area_notes=[]; codes={}
    for k,cell in (('LCR',lcr),('NL',nl)):
        code,txt=clean_code(cell)
        if code: codes[k]=code
        if txt: area_notes.append(f"{k} column note: {txt}")
        # note when code cleaned with note
    # re-handle codes with notes returning both
    for k,cell in (('LCR',lcr),('NL',nl)):
        code,txt=clean_code(cell)
    shared=[]  # values (time) notes
    tnotes=[]; r_vals={}
    # first flowering
    obs=[]
    underlined=False
    for lab,cell in (("first flowering Resp",ffr),("first flowering Seed",ffs)):
        if not cell: continue
        if cell.startswith('Note:') or re.match(r'^(Leaves emerged|Resprouted, low)',cell):
            obs.append(f"{lab} column text: {cell}"); continue
        u,parts=parse_time(cell)
        if u:
            if not any('unclear' in o and cell_print(parts) in o for o in obs):
                obs.append(f"first flowering {cell_print(parts)} (underlined: unclear whether resprouts or plants from seed), not filled in repr3 or repr3a")
            continue
        if any(p.get('bad') for p in parts) and not any(not p.get('bad') for p in parts):
            obs.append(f"{lab} column text: {cell}"); continue
        col="Time to first flower production resprout_repr3a" if lab.endswith('Resp') else "Age at first flower production from seed_repr3"
        v=val_fixed(parts,col,tnotes,lab)
        if v: r_vals[col]=v
    for lab,cell in (("first fruiting Resp",frr),("first fruiting Seed",frs)):
        if cell:
            u,parts=parse_time(cell)
            obs.append(f"{lab} {cell.replace('<u>','').replace('</u>','')}"+(" (underlined: unclear whether resprouts or plants from seed)" if u else "")+" (no fruiting column)")
    if seed: obs.append(f"seedlings first observed {seed}")
    if peak: obs.append(f"post-fire peak printed '{peak}'")
    sv=None
    pjv=suv=''
    unit=''
    if pj:
        v,_=pjp(pj,"primary_juvenile_period",tnotes,False)
        if v: r_vals["primary_juvenile_period"]=v
    if sj:
        v,un=pjp(sj,"secondary_juvenile_period",tnotes,True)
        if v: r_vals["secondary_juvenile_period"]=v; unit=un
    return dict(page=page,fam=fam,g=g,sp=sp,sub=sub,exotic=exotic,poss=poss,nnote=nnote,codes=codes,area_notes=area_notes,vals=r_vals,unit=unit,tnotes=tnotes,obs=obs,raw=raw_row)
def make_rows(b):
    page=b['page']
    out=[]
    base={"Genus":b['g'],"Species":b['sp'],"subsp":b['sub'],"scientific_name":f"{b['g']} {b['sp']}","Family":b['fam'],"Fire_type":"wildfire","Fire_season_categorical":"Summer","Fire_severity_categorical":"High","Source":SRC,"File_name":stem}
    if b['exotic']: base["native_status"]="exotic"
    elif not b['poss']: base["native_status"]="native"
    src=f"Appendix 1, p. {page}"
    def notes(extra_row,fr_note=None,tn=True,obs=True,site_note=None):
        n=[src]
        if fr_note: n.append(fr_note)
        if b['nnote']: n.append(b['nnote'])
        if b['poss']: n.append("native_status left empty: name printed with '(*?)' (possibly exotic)")
        if tn: n+=b['tnotes']
        if obs and b['obs']: n.append("other observations: "+'; '.join(b['obs']))
        n+=b['area_notes']
        n+=extra_row
        n.append(PW)
        return '; '.join(n)
    areas=list(b['codes'].keys())
    vals=b['vals']
    def frcol(code):
        return "resprouter" if code=='R' else ("obligate" if code=='K' else code)
    def area_row(k,with_vals):
        code=b['codes'][k]
        r=dict(base); r["Location_name"]=LCRN if k=='LCR' else NLN; r["Latitude"]="-33.75"; r["Longitude"]="151.0833"
        r["fire_response categorical_surv1"]=frcol(code)
        if with_vals:
            for c_,v in vals.items(): r[c_]=v
            if b['unit']: r["Time_unit"]=b['unit']
        fn=f"fire_response categorical_surv1 from {code_def(code)}" if code in('R','K') else f"fire_response categorical_surv1 copied as printed, {code_def(code) if re.fullmatch(r'[?pKkRr/;]+',code) else 'see notes'}"
        r["Notes"]=notes([],fn,tn=with_vals,obs=with_vals)
        return r
    if len(areas)==1:
        out.append(area_row(areas[0],True))
    elif len(areas)==2:
        for k in areas: out.append(area_row(k,False))
        if vals:
            r=dict(base); r["Location_name"]=f"{LCRN}; {NLN}"
            for c_,v in vals.items(): r[c_]=v
            if b['unit']: r["Time_unit"]=b['unit']
            r["Notes"]=notes([ "values given once for both areas (not split by site)"])
            out.append(r)
        else:
            # attach obs/area notes only to area rows: rebuild with obs
            out=[]
            for k in areas:
                r=area_row(k,False)
                if b['obs']:
                    r["Notes"]=r["Notes"].replace("; "+PW,"; other observations: "+'; '.join(b['obs'])+"; "+PW)
                out.append(r)
    else:
        if vals:
            r=dict(base); r["Location_name"]=f"{LCRN}; {NLN}"
            for c_,v in vals.items(): r[c_]=v
            if b['unit']: r["Time_unit"]=b['unit']
            r["Notes"]=notes(["no Lane Cove River or Narrabeen Lagoon code printed; values given once for both areas"])
            out.append(r)
    return out
if __name__=="__main__":
    allrows=[]; 
    built=[build(r) for r in SRC_ROWS]
    for b in built: allrows+=make_rows(b)
    print("total rows",len(allrows))
    if len(sys.argv)>1 and sys.argv[1]=="show":
        random.seed(5)
        for b in random.sample(built,3):
            print("SRC",b['raw'][3],b['raw'][2])
            for r in make_rows(b): print({k:v for k,v in r.items() if v and k not in('Source','File_name')})
            print()
    else:
        finish(stem,allrows,sys.argv[1],f"Appendix 1: {len(SRC_ROWS)} species rows; species recorded in both areas get 1 row per area (fire response) plus 1 shared row for time values; underlined bridging values and fruiting times in Notes only")
E
