PW="fire responses are for plants with 100% leaf scorch in the January 1994 wildfires, Lane Cove River fire began 6 January 1994 and Narrabeen Lagoon fire 8 January 1994, generally of very high intensity (p. 133 and p. 134); Latitude and Longitude converted from 'lat 33° 45' S, long 151° 05' E' (p. 131); Fire_season_categorical derived from fire dates in January 1994; Fire_type wildfire from 'wildfires'; unmarked species counted as native, * = exotic species (576 native and 252 exotic species, p. 145); first flowering Resp = resprouted plants, Seed = plants from seed (p. 145)"
DEF={"R":"majority of adult plants resprouted","K":"majority of adult plants killed","r":"small proportion of adult plants resprouted","k":"small proportion of adult plants killed"}
def fmt(x):
    s=f"{x:.3f}".rstrip('0').rstrip('.'); return s
def w2y(x): return fmt(float(x)/52)
def code_def(code):
    parts=re.findall(r'(p|\?)?([RKrk])',code); out=[]
    for pre,l in parts:
        d=DEF[l]
        if pre=='p': d='probably '+d
        elif pre=='?': d='possibly '+d
        out.append(f"{l} = {d}")
    return f"code '{code}': "+"; ".join(out)
def clean_code(c):
    c=c.strip()
    if re.fullmatch(r'[?pKkRr/; ]+',c): return re.sub(r'\s+','',c),None
    m=re.match(r'^(R)\(1\)m\.i\.f (.*)$',c)
