def cell_print(parts): return ','.join(p['raw'] for p in parts)
def pjp(cell,col,notes,variable):
    c=cell.strip()
    m=re.fullmatch(r'At least (\d+) years?',c)
    if m: notes.append(f"{col} printed '{c}'"); return '>'+m.group(1),'years'
    m=re.fullmatch(r'Less than (\d+) years?',c)
