import sys,re,collections,random; sys.path.insert(0,'/tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/e22fd76a-04d4-41fa-bf12-fc718952c66e/scratchpad')
from h import *
from nparse import pages
stem="nswfrrd_v1.3a_pdfvers_sppdata"
SRC=stem
PW="database printout of species fire response and vital attributes for New South Wales plants; fire response codes are not defined in the printout and are copied as printed; no study site, coordinates, fire date or rainfall given; juvenile periods and recommended minimum interval are printed without a unit, so the time columns are left empty"
def pname(n):
    raw=n
    n=n.replace('novae- ','novae-').replace('luteo- ','luteo-').replace('novae- ','novae-')
    n=re.sub(r'\bsubsp\b(?!\.)','subsp.',n); n=re.sub(r'\bvar\b(?!\.)','var.',n); n=re.sub(r'\bforma\b','f.',n)
    t=n.split(); g=t[0]; rest=t[1:]
    sub=''
    if rest and rest[0]=='sp.':
        sp=' '.join(rest); 
    else:
        sp=rest[0]; r2=rest[1:]
        if r2: sub=' '.join(r2)
    return g,sp,sub,(raw if raw!=(f"{g} {sp}"+(f" {sub}" if sub else '')) else None)
rows=[]; cnt=collections.Counter()
names_all=[r[0] for i in range(0,len(pages),2) for r in pages[i][3]]
dup={k for k,v in collections.Counter(names_all).items() if v>1}
for i in range(0,len(pages),2):
    a,b=pages[i],pages[i+1]; assert a[1]=='A' and b[1]=='B'
    for ra,rb in zip(a[3],b[3]):
        assert ra[0]==rb[0]
        name,syn,fam,fr,com,seedst,disp,germ,nfrr,addl=ra
        vag,sf,si,pj,sj,rmi,life,cons,dist,veg,fl=rb[1:]
        g,sp,sub,printed=pname(name)
        n=[]
        if name in dup:
            diff=f"fire response '{fr}'"+(f", comments '{com}'" if com else '')+(f", additional fire response data '{addl}'" if addl else '')+(f", NFRR data '{nfrr}'" if nfrr else '')
            n.append(f"separate entry in paper: same taxon printed in more than one entry, this entry has {diff}")
        n.append(f"PDF p. {a[0]}; PDF p. {b[0]}")
        n.append("fire_response categorical_surv1 copied as printed")
        if printed: n.append(f"name printed as '{printed}'")
        if syn: n.append(f"synonym printed as '{syn}'")
        if com: n.append(f"comments on regeneration: {com}")
        if pj: n.append(f"primary juvenile printed as '{pj}' (unit not stated)")
        if sj: n.append(f"secondary juvenile period printed as '{sj}' (unit not stated)")
        if rmi: n.append(f"recommended minimum interval printed as '{rmi}' (unit not stated)")
        if life: n.append(f"lifespan + seedbank printed as '{life}'")
        if nfrr: n.append(f"NFRR data: {nfrr}")
        if addl: n.append(f"additional fire response data: {addl}")
        n.append(PW)
        r={"Genus":g,"Species":sp,"subsp":sub,"scientific_name":f"{g} {sp}","Family":fam,"fire_response categorical_surv1":fr,"Notes":"; ".join(n),"Source":SRC,"File_name":stem}
        if dist=='Exotic': r["native_status"]="exotic"; r["Notes"]=r["Notes"].replace("; "+PW,"; native_status 'exotic' from 'Exotic' in the Distribution: NSW column; "+PW)
        rows.append(r)
print(len(rows))
if len(sys.argv)>1 and sys.argv[1]=="show":
    random.seed(7)
    for r in random.sample(rows,3): print({k:v for k,v in r.items() if v and k not in('Source','File_name')})
else:
